mkdir -p /workspace/klee-analysis && cat > /workspace/klee-analysis/harness_base64.c << 'HARNESS_EOF'
/*
 * KLEE harness for masscan's base64_encode function.
 * Tests the base64 encoding function with symbolic input data and sizes.
 * Looks for potential buffer overflows or out-of-bounds accesses.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "klee/klee.h"

/* Declare the function under test */
size_t base64_encode(void *vdst, size_t sizeof_dst,
              const void *vsrc, size_t sizeof_src);

size_t base64_decode(void *vdst, size_t sizeof_dst,
              const void *vsrc, size_t sizeof_src);

int main() {
    /* Fixed-size buffers for symbolic execution */
    unsigned char src[16];
    unsigned char dst[64];

    /* Make source data symbolic */
    klee_make_symbolic(src, sizeof(src), "src");

    /* Symbolic source length (constrained to valid range) */
    size_t src_len;
    klee_make_symbolic(&src_len, sizeof(src_len), "src_len");
    klee_assume(src_len <= sizeof(src));

    /* Symbolic destination size (constrained to valid range) */
    size_t dst_len;
    klee_make_symbolic(&dst_len, sizeof(dst_len), "dst_len");
    klee_assume(dst_len <= sizeof(dst));

    /* Call base64_encode - KLEE will explore all paths */
    size_t encoded_len = base64_encode(dst, dst_len, src, src_len);

    /* Check: encoded output should not exceed dst_len */
    klee_assert(encoded_len <= dst_len);

    /* Also test base64_decode with the encoded output */
    unsigned char decoded[16];
    size_t decoded_len = base64_decode(decoded, sizeof(decoded), dst, encoded_len);

    /* Check: decoded output should not exceed buffer */
    klee_assert(decoded_len <= sizeof(decoded));

    return 0;
}
HARNESS_EOF
echo "Harness for base64 created"

