/*
 * KLEE harness for masscan's blackrock shuffle function.
 * Tests the BlackRock cipher (Feistel network) with symbolic inputs.
 * Verifies the 1-to-1 mapping property of the shuffle.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "klee/klee.h"

/* Declare the BlackRock structure and functions */
struct BlackRock {
    uint64_t range;
    uint64_t a;
    uint64_t b;
    uint64_t seed;
    unsigned rounds;
    uint64_t a_bits;
    uint64_t a_mask;
    uint64_t b_bits;
    uint64_t b_mask;
};

void blackrock_init(struct BlackRock *br, uint64_t range, uint64_t seed, unsigned rounds);
uint64_t blackrock_shuffle(const struct BlackRock *br, uint64_t index);
uint64_t blackrock_unshuffle(const struct BlackRock *br, uint64_t m);

int main() {
    struct BlackRock br;

    /* Symbolic seed and range */
    uint64_t seed;
    uint64_t index;

    klee_make_symbolic(&seed, sizeof(seed), "seed");
    klee_make_symbolic(&index, sizeof(index), "index");

    /* Use a small fixed range for tractability */
    uint64_t range = 100;
    unsigned rounds = 4;

    /* Initialize BlackRock cipher */
    blackrock_init(&br, range, seed, rounds);

    /* Constrain index to be within range */
    klee_assume(index < range);

    /* Shuffle the index */
    uint64_t shuffled = blackrock_shuffle(&br, index);

    /* The shuffled value should be within range */
    klee_assert(shuffled < range);

    /* Unshuffle should give back the original index */
    uint64_t unshuffled = blackrock_unshuffle(&br, shuffled);
    klee_assert(unshuffled == index);

    return 0;
}
HARNESS_EOF
echo "Harness for blackrock created"

