/*
 * KLEE harness for masscan's rangelist_is_contains function.
 * Tests the IP range containment check with symbolic address.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include "klee/klee.h"

/* Declare the Range and RangeList structures */
struct Range
{
    unsigned begin;
    unsigned end;
};

struct RangeList
{
    struct Range *list;
    unsigned count;
    unsigned max;
    unsigned *picker;
    unsigned is_sorted:1;
};

int rangelist_is_contains(const struct RangeList *targets, unsigned addr);

int main() {
    /* Create a range list with a fixed set of ranges */
    struct Range ranges[3];

    /* Fixed ranges for testing containment */
    ranges[0].begin = 0x0a000000; /* 10.0.0.0 */
    ranges[0].end   = 0x0a0000ff; /* 10.0.0.255 */
    ranges[1].begin = 0xc0a80000; /* 192.168.0.0 */
    ranges[1].end   = 0xc0a800ff; /* 192.168.0.255 */
    ranges[2].begin = 0xac100000; /* 172.16.0.0 */
    ranges[2].end   = 0xac100fff; /* 172.16.15.255 */

    struct RangeList targets;
    targets.list = ranges;
    targets.count = 3;
    targets.max = 3;
    targets.picker = NULL;
    targets.is_sorted = 1;

    /* Symbolic address to test */
    unsigned addr;
    klee_make_symbolic(&addr, sizeof(addr), "addr");

    /* Call rangelist_is_contains */
    int result = rangelist_is_contains(&targets, addr);

    /* The result should be 0 or 1 */
    klee_assert(result == 0 || result == 1);

    return 0;
}
