/*
 * KLEE harness for masscan's preprocess_frame function.
 * Tests the packet parsing function with symbolic input.
 * Looks for potential buffer overflows or out-of-bounds accesses.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "klee/klee.h"

/* Include the header */
#include "proto-preprocess.h"

int main() {
    /* Fixed-size packet buffer */
    unsigned char packet[128];
    struct PreprocessedInfo info;

    /* Make packet data symbolic */
    klee_make_symbolic(packet, sizeof(packet), "packet");

    /* Symbolic length - constrained to buffer size */
    unsigned length;
    klee_make_symbolic(&length, sizeof(length), "length");
    klee_assume(length <= sizeof(packet));

    /* Fixed link_type = 1 (Ethernet) */
    unsigned link_type = 1;

    /* Call preprocess_frame - KLEE will explore all parsing paths */
    unsigned result = preprocess_frame(packet, length, link_type, &info);

    /* Result should be 0 or 1 */
    klee_assert(result == 0 || result == 1);

    /* If result is 1, the info fields should be valid */
    if (result == 1) {
        /* IP version should be 4 or 6 if found */
        if (info.found == FOUND_IPV4 || info.found == FOUND_IPV6) {
            klee_assert(info.ip_version == 4 || info.ip_version == 6);
        }
        /* Offsets should be within packet bounds */
        klee_assert(info.ip_offset <= length);
        klee_assert(info.transport_offset <= length);
    }

    return 0;
}
HARNESS_EOF

