unsigned checksum_ipv4(unsigned ip_src, unsigned ip_dst, unsigned ip_proto, size_t payload_length, const void *payload);

int main() {
    /* Fixed-size payload buffer */
    unsigned char payload[64];

    /* Make payload data symbolic */
    klee_make_symbolic(payload, sizeof(payload), "payload");

    /* Symbolic IP addresses */
    unsigned ip_src, ip_dst;
    klee_make_symbolic(&ip_src, sizeof(ip_src), "ip_src");
    klee_make_symbolic(&ip_dst, sizeof(ip_dst), "ip_dst");

    /* Symbolic protocol - constrained to known values (0,1,2,6,17) */
    unsigned ip_proto;
    klee_make_symbolic(&ip_proto, sizeof(ip_proto), "ip_proto");
    klee_assume(ip_proto == 0 || ip_proto == 1 || ip_proto == 2 || 
                ip_proto == 6 || ip_proto == 17);

    /* Symbolic payload length - constrained to buffer size */
    size_t payload_length;
    klee_make_symbolic(&payload_length, sizeof(payload_length), "payload_length");
    klee_assume(payload_length <= sizeof(payload));
    klee_assume(payload_length >= 8); /* minimum for protocol checks */

    /* Call checksum_ipv4 - KLEE will explore all paths */
    unsigned result = checksum_ipv4(ip_src, ip_dst, ip_proto, payload_length, payload);

    /* The checksum should be a 16-bit value */
    klee_assert((result & 0xFFFF0000) == 0 || result == 0xFFFFFFFF);

    return 0;
}
